import { config } from "dotenv";
import { neon, Pool } from "@neondatabase/serverless";

// Load environment variables from .env.local (generated by neon deploy) and fallback to .env
config({ path: ".env.local" });
config({ path: ".env" });

export interface DatabaseDiagnostics {
  status: "connected" | "error";
  pooledHost: string;
  unpooledHost?: string;
  currentDatabase: string;
  currentUser: string;
  version: string;
  serverTime: string;
  branchName?: string;
  branchId?: string;
  error?: string;
}

export interface E2ETestResult {
  step: string;
  status: "PASSED" | "FAILED";
  details?: any;
  durationMs: number;
}

function parseHostFromUrl(connectionUrl?: string): string {
  if (!connectionUrl) return "NOT_SET";
  try {
    const parsed = new URL(connectionUrl);
    return parsed.hostname;
  } catch {
    return "INVALID_URL";
  }
}

export function getDatabaseUrls() {
  const databaseUrl = process.env.DATABASE_URL;
  const databaseUrlUnpooled = process.env.DATABASE_URL_UNPOOLED;

  if (!databaseUrl) {
    throw new Error(
      "DATABASE_URL is not defined in environment or .env.local. Run `neon deploy` to pull environment variables."
    );
  }

  return {
    databaseUrl,
    databaseUrlUnpooled,
    branchName: process.env.NEON_BRANCH,
    branchId: process.env.NEON_BRANCH_ID,
  };
}

/**
 * Primary serverless SQL query client using @neondatabase/serverless over HTTPS.
 * Best practice for serverless and application read/write query traffic on Neon.
 */
export function createSqlClient(url?: string) {
  const targetUrl = url || getDatabaseUrls().databaseUrl;
  return neon(targetUrl);
}

/**
 * Standard WebSocket connection pool for long-lived/transactional workloads.
 */
export function createConnectionPool(url?: string) {
  const targetUrl = url || getDatabaseUrls().databaseUrl;
  return new Pool({ connectionString: targetUrl });
}

/**
 * Executes deep health check and metadata introspection on the connected Neon Postgres instance.
 */
export async function runDiagnostics(): Promise<DatabaseDiagnostics> {
  const { databaseUrl, databaseUrlUnpooled, branchName, branchId } = getDatabaseUrls();
  const sql = createSqlClient(databaseUrl);

  try {
    const rows = await sql`
      SELECT 
        version() as version,
        current_database() as current_database,
        current_user as current_user,
        now() as server_time;
    `;

    const row = rows[0];

    return {
      status: "connected",
      pooledHost: parseHostFromUrl(databaseUrl),
      unpooledHost: parseHostFromUrl(databaseUrlUnpooled),
      currentDatabase: String(row.current_database),
      currentUser: String(row.current_user),
      version: String(row.version),
      serverTime: new Date(String(row.server_time)).toISOString(),
      branchName: branchName || undefined,
      branchId: branchId || undefined,
    };
  } catch (error: any) {
    return {
      status: "error",
      pooledHost: parseHostFromUrl(databaseUrl),
      unpooledHost: parseHostFromUrl(databaseUrlUnpooled),
      currentDatabase: "unknown",
      currentUser: "unknown",
      version: "unknown",
      serverTime: new Date().toISOString(),
      branchName: branchName || undefined,
      branchId: branchId || undefined,
      error: error?.message || String(error),
    };
  }
}

/**
 * Runs a complete End-to-End database verification cycle:
 * 1. Connectivity test
 * 2. Schema DDL test (create test table)
 * 3. DML Write test (insert test record)
 * 4. DML Read test (verify inserted record)
 * 5. Clean-up (drop test table)
 */
export async function runEndToEndVerification(): Promise<E2ETestResult[]> {
  const { databaseUrl } = getDatabaseUrls();
  const sql = createSqlClient(databaseUrl);
  const results: E2ETestResult[] = [];

  // Step 1: Connectivity Verification
  let stepStart = Date.now();
  try {
    const pingResult = await sql`SELECT 1 as ping;`;
    results.push({
      step: "1. Neon Postgres Connectivity Ping",
      status: pingResult[0]?.ping === 1 ? "PASSED" : "FAILED",
      details: { ping: pingResult[0]?.ping },
      durationMs: Date.now() - stepStart,
    });
  } catch (err: any) {
    results.push({
      step: "1. Neon Postgres Connectivity Ping",
      status: "FAILED",
      details: err.message,
      durationMs: Date.now() - stepStart,
    });
    return results;
  }

  // Step 2: DDL Table Creation
  stepStart = Date.now();
  try {
    await sql`
      CREATE TABLE IF NOT EXISTS _neon_e2e_verify (
        id SERIAL PRIMARY KEY,
        service_name VARCHAR(100) NOT NULL,
        test_payload JSONB NOT NULL,
        created_at TIMESTAMPTZ NOT NULL DEFAULT NOW()
      );
    `;
    results.push({
      step: "2. DDL Table Creation (CREATE TABLE)",
      status: "PASSED",
      details: { table: "_neon_e2e_verify" },
      durationMs: Date.now() - stepStart,
    });
  } catch (err: any) {
    results.push({
      step: "2. DDL Table Creation (CREATE TABLE)",
      status: "FAILED",
      details: err.message,
      durationMs: Date.now() - stepStart,
    });
    return results;
  }

  // Step 3: DML Insert (Write)
  stepStart = Date.now();
  const payloadStr = JSON.stringify({ milestone: "0.1", status: "active", environment: "production" });
  try {
    const insertResult = await sql`
      INSERT INTO _neon_e2e_verify (service_name, test_payload)
      VALUES ('neon-postgres', ${payloadStr}::jsonb)
      RETURNING id, service_name, test_payload, created_at;
    `;
    results.push({
      step: "3. DML Write Verification (INSERT INTO)",
      status: "PASSED",
      details: insertResult[0],
      durationMs: Date.now() - stepStart,
    });
  } catch (err: any) {
    results.push({
      step: "3. DML Write Verification (INSERT INTO)",
      status: "FAILED",
      details: err.message,
      durationMs: Date.now() - stepStart,
    });
  }

  // Step 4: DML Select (Read Verification)
  stepStart = Date.now();
  try {
    const selectResult = await sql`
      SELECT id, service_name, test_payload, created_at 
      FROM _neon_e2e_verify
      WHERE service_name = 'neon-postgres'
      ORDER BY id DESC
      LIMIT 1;
    `;
    const verified = selectResult.length === 1 && selectResult[0].service_name === "neon-postgres";
    results.push({
      step: "4. DML Read Verification (SELECT FROM)",
      status: verified ? "PASSED" : "FAILED",
      details: selectResult[0],
      durationMs: Date.now() - stepStart,
    });
  } catch (err: any) {
    results.push({
      step: "4. DML Read Verification (SELECT FROM)",
      status: "FAILED",
      details: err.message,
      durationMs: Date.now() - stepStart,
    });
  }

  // Step 5: Clean-up (DROP TABLE)
  stepStart = Date.now();
  try {
    await sql`DROP TABLE IF EXISTS _neon_e2e_verify;`;
    results.push({
      step: "5. DDL Cleanup Verification (DROP TABLE)",
      status: "PASSED",
      details: { droppedTable: "_neon_e2e_verify" },
      durationMs: Date.now() - stepStart,
    });
  } catch (err: any) {
    results.push({
      step: "5. DDL Cleanup Verification (DROP TABLE)",
      status: "FAILED",
      details: err.message,
      durationMs: Date.now() - stepStart,
    });
  }

  return results;
}
